// Pull ticket payload from the webhook trigger and build the classify
// system prompt + user message. Settings prompt overrides the inline
// fallback if seeded into the settings table.
const ticket = $('Webhook Trigger').first().json.body || $('Webhook Trigger').first().json;
const settingsRows = $input.first().json || [];
const byKey = {};
if (Array.isArray(settingsRows)) for (const r of settingsRows) byKey[r.key] = r.value;

const t0 = Date.now();

const CLASSIFY_SYSTEM = (byKey.prompt_classify_v1 && typeof byKey.prompt_classify_v1 === 'string') ? byKey.prompt_classify_v1 : `You classify incoming support tickets for Instantly.ai into one of six categories. You are precise and conservative.

Categories — exact spelling required:
- "how_to_question": customer wants to know how to do something.
- "bug_report": something broken or behaving wrong.
- "feature_request": customer wants a capability that does not exist.
- "account_issue": access, login, ownership, permissions, lockout, password reset.
- "billing": invoices, charges, subscription, refunds, payment methods, plans, credits.
- "other": doesn't cleanly fit above.

Output schema — JSON only, no surrounding prose:
{
  "category": "<one of the six labels>",
  "classification_confidence": <float 0.0-1.0>,
  "reasoning": "<one sentence, max 30 words>"
}

Confidence calibration:
- 0.9-1.0: clearly fits one category
- 0.7-0.89: fits one but mentions another in passing
- 0.5-0.69: two categories plausible
- below 0.5: genuinely ambiguous

Never output text outside the JSON object.`;

const userMsg = `Subject: ${ticket.subject}\n\nBody:\n${ticket.body}`;

return {
  json: {
    ticket_id: ticket.ticket_id,
    subject: ticket.subject,
    body: ticket.body,
    customer_email: ticket.customer_email,
    settings: byKey,
    t0,
    classify_system: CLASSIFY_SYSTEM,
    classify_user: userMsg
  }
};

// Strict JSON parse on Anthropic response. On parse failure, mark the
// run so downstream nodes route to human review with the raw output
// preserved for debugging.
const prev = $('Build Classify Prompt').first().json;
const resp = $input.first().json;
const raw = resp?.content?.[0]?.text || '';
let classification = null;
let parse_error = null;
try {
  const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  classification = JSON.parse(cleaned);
} catch (err) {
  parse_error = String(err.message || err);
}
return {
  json: {
    ...prev,
    classification,
    classify_raw: raw,
    classify_parse_error: parse_error
  }
};

// Compute L1 cosine signal + decide whether to short-circuit.
// Short-circuit conditions:
//   - classify parse failed -> route to human with reason 'malformed_llm_output_classify'
//   - retrieval returned 0 chunks or top1 below hard floor -> cannot_answer
// Otherwise proceed to drafting.
const prev = $('Parse Classification').first().json;
const chunks = ($input.first().json) || [];
const arr = Array.isArray(chunks) ? chunks : (chunks.data || []);

const top1 = arr[0]?.similarity ?? null;
const top2 = arr[1]?.similarity ?? null;
const margin = top1 != null && top2 != null ? (top1 - top2) : null;

const hardFloor = Number(prev.settings?.hard_floor_top1_cosine ?? 0.5);

let should_short_circuit = false;
let short_circuit_verdict = null;
let short_circuit_reason = null;

if (prev.classify_parse_error) {
  should_short_circuit = true;
  short_circuit_verdict = 'error';
  short_circuit_reason = 'malformed_llm_output_classify';
}
if (!should_short_circuit && arr.length === 0) {
  should_short_circuit = true;
  short_circuit_verdict = 'cannot_answer';
  short_circuit_reason = 'no_kb_match';
}
if (!should_short_circuit && top1 != null && top1 < hardFloor) {
  should_short_circuit = true;
  short_circuit_verdict = 'cannot_answer';
  short_circuit_reason = `top1_below_hard_floor (${top1.toFixed(3)} < ${hardFloor})`;
}

return {
  json: {
    ...prev,
    top_chunks: arr.map((c) => ({
      chunk_id: c.chunk_id,
      doc_url: c.doc_url,
      doc_title: c.doc_title,
      category: c.category,
      section_heading: c.section_heading,
      score: c.similarity,
      content_snippet: (c.content || '').slice(0, 500)
    })),
    top_chunks_full: arr, // includes full content for the draft prompt
    top1,
    top2,
    margin,
    should_short_circuit,
    short_circuit_verdict,
    short_circuit_reason
  }
};

// Build the category-conditioned draft prompt.
const prev = $json;
const chunks = prev.top_chunks_full || [];
const category = prev.classification?.category || 'other';

const DRAFT_SYSTEM = (prev.settings?.prompt_draft_v1 && typeof prev.settings.prompt_draft_v1 === 'string') ? prev.settings.prompt_draft_v1 : `You are an Instantly.ai support agent drafting a reply. Your reply must be grounded in the help-center chunks provided. No general world knowledge about Instantly may enter the reply.

Rules:
1. The reply must be answerable from the chunks. If not, output {"cannot_answer": true, "reason": "...", "used_chunk_ids": []}.
2. Quote or closely paraphrase the chunks you used. List used chunk_ids and doc_urls.
3. Tone: direct, friendly, second-person. No hedging openers. No markdown headers, no emojis.
4. End with: "Full guide: <doc_url>"
5. Category guidance:
  - how_to_question: answer if chunks describe steps. <=120 words.
  - billing: only answer if chunks have the exact policy. Customer-specific charges -> cannot_answer with reason "customer-specific billing".
  - bug_report: only answer if chunks describe a known workaround for the exact symptom. Else cannot_answer with reason "no documented workaround for this symptom".
  - feature_request: only answer if chunks confirm the feature exists. Else cannot_answer with reason "feature existence not confirmed in knowledge base".
  - account_issue: ALWAYS cannot_answer with reason "account access requires human review".
  - other: cannot_answer with reason "out of scope for auto-reply".

Output schema — JSON only, no prose. Either:
{
  "answer": "<text ending with 'Full guide: <url>'>",
  "cited_doc_urls": ["<url>", ...],
  "used_chunk_ids": ["<chunk_id>", ...]
}
Or:
{
  "cannot_answer": true,
  "reason": "<one of the reasons listed above>",
  "used_chunk_ids": []
}`;

const chunksBlock = chunks.map((c, i) => `[chunk_id=${c.chunk_id}  similarity=${(c.similarity ?? 0).toFixed(3)}  doc_url=${c.doc_url}  section="${c.section_heading ?? ''}"]\n${c.content}`).join('\n\n');

const userMsg = `Predicted category: ${category}\n\nSubject: ${prev.subject}\n\nBody:\n${prev.body}\n\nRetrieved chunks (top ${chunks.length}, ordered by similarity desc):\n\n${chunksBlock}`;

return {
  json: {
    ...prev,
    draft_system: DRAFT_SYSTEM,
    draft_user: userMsg
  }
};

// Parse draft. Capture either answer-shape or cannot_answer-shape.
const prev = $('Build Draft Prompt').first().json;
const raw = $input.first().json?.content?.[0]?.text || '';
let parsed = null;
let parse_error = null;
try {
  const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  parsed = JSON.parse(cleaned);
} catch (err) {
  parse_error = String(err.message || err);
}

const draft_response = parsed?.answer ?? null;
const cited_doc_urls = parsed?.cited_doc_urls ?? [];
const used_chunk_ids = parsed?.used_chunk_ids ?? [];
const cannot_answer = parsed?.cannot_answer === true;
const cannot_answer_reason = parsed?.reason || null;

const cited_docs = (cited_doc_urls || []).map((url) => {
  const match = (prev.top_chunks || []).find((c) => c.doc_url === url);
  return { doc_url: url, doc_title: match?.doc_title || url };
});

return {
  json: {
    ...prev,
    draft_raw: raw,
    draft_parse_error: parse_error,
    draft_response,
    cited_doc_urls,
    used_chunk_ids,
    cited_docs,
    cannot_answer,
    cannot_answer_reason
  }
};

// Build self-grade prompt. Skip self-grade entirely when the drafter
// declined (cannot_answer) — we already know we're routing to human.
const prev = $json;
if (prev.cannot_answer || prev.draft_parse_error || !prev.draft_response) {
  return { json: { ...prev, skip_self_grade: true } };
}

const SG_SYSTEM = (prev.settings?.prompt_self_grade_v1 && typeof prev.settings.prompt_self_grade_v1 === 'string') ? prev.settings.prompt_self_grade_v1 : `You evaluate a draft support reply against the customer ticket and retrieved help-center chunks. Be skeptical: false positives are far costlier than false negatives.

Score three axes 1-5:
- GROUNDED_IN_CITED_DOC: does the draft's content actually appear in cited chunks? 5=verbatim/near-verbatim everywhere, 1=hallucinated.
- DIRECTLY_ANSWERS_QUESTION: 5=exact, 1=off-topic.
- TONE_APPROPRIATE: 5=clean on-brand, 1=embarrassing.

Output JSON only:
{
  "grounded_in_cited_doc": <int 1-5>,
  "directly_answers_question": <int 1-5>,
  "tone_appropriate": <int 1-5>,
  "justification": "<two sentences max — what drove the lowest score>"
}

Never output text outside the JSON object.`;

const chunks = prev.top_chunks_full || [];
const chunksBlock = chunks.map((c, i) => `[chunk_id=${c.chunk_id}  similarity=${(c.similarity ?? 0).toFixed(3)}]\n${c.content}`).join('\n\n');

const userMsg = `Ticket subject: ${prev.subject}\nTicket body:\n${prev.body}\n\nRetrieved chunks the drafter saw:\n\n${chunksBlock}\n\nDraft reply:\n${prev.draft_response}\n\nCited doc URLs from drafter: ${JSON.stringify(prev.cited_doc_urls)}\nUsed chunk ids from drafter: ${JSON.stringify(prev.used_chunk_ids)}`;

return {
  json: {
    ...prev,
    sg_system: SG_SYSTEM,
    sg_user: userMsg
  }
};

// Parse self-grade and compute the final verdict using the multi-signal
// gate. Auto-send requires:
//   - top1 >= cosine_floor AND (top1 - top2) >= cosine_margin
//   - min(grounded, directly_answers) >= self_grade_floor
// Otherwise human_review (or cannot_answer if drafter declined).
const prev = $('Build Self-Grade Prompt').first().json;
const rawSg = $input.first().json?.content?.[0]?.text || '';
let self_grade = null;
let sg_parse_error = null;
if (!prev.skip_self_grade) {
  try {
    const cleaned = rawSg.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
    self_grade = JSON.parse(cleaned);
  } catch (err) {
    sg_parse_error = String(err.message || err);
  }
}

const cosineFloor = Number(prev.settings?.cosine_floor ?? 0.78);
const cosineMargin = Number(prev.settings?.cosine_margin ?? 0.05);
const sgFloor = Number(prev.settings?.self_grade_floor ?? 4);

const top1 = prev.top1;
const top2 = prev.top2;
const margin = prev.margin;

let verdict = 'human_review';
let verdict_reason = 'unspecified';

if (prev.cannot_answer) {
  verdict = 'cannot_answer';
  verdict_reason = `drafter_declined:${prev.cannot_answer_reason || 'unspecified'}`;
} else if (prev.draft_parse_error) {
  verdict = 'human_review';
  verdict_reason = `malformed_llm_output_draft`;
} else if (sg_parse_error) {
  verdict = 'human_review';
  verdict_reason = `malformed_llm_output_self_grade`;
} else if (!self_grade) {
  verdict = 'human_review';
  verdict_reason = `self_grade_missing`;
} else {
  // both L1 and L2 must pass for auto_send
  const l1Pass = top1 != null && top2 != null && top1 >= cosineFloor && margin >= cosineMargin;
  const sgMin = Math.min(self_grade.grounded_in_cited_doc, self_grade.directly_answers_question);
  const l2Pass = sgMin >= sgFloor;
  if (l1Pass && l2Pass) {
    verdict = 'auto_send';
    verdict_reason = `cos=${top1.toFixed(3)} mar=${margin.toFixed(3)} sg=${sgMin}`;
  } else if (!l1Pass) {
    verdict_reason = top1 == null ? 'no_top1' : (top1 < cosineFloor ? `top1_cosine_below_floor (${top1.toFixed(3)} < ${cosineFloor})` : `margin_below_floor (${margin.toFixed(3)} < ${cosineMargin})`);
  } else {
    verdict_reason = `self_grade_below_floor (min=${sgMin} < ${sgFloor})`;
  }
}

const latency_ms = Date.now() - (prev.t0 || Date.now());

return {
  json: {
    ticket_id: prev.ticket_id,
    classification: prev.classification,
    top_chunks: prev.top_chunks,
    draft_response: prev.draft_response,
    cited_docs: prev.cited_docs,
    self_grade,
    verdict,
    verdict_reason,
    latency_ms,
    prompt_versions: { classify: 'v1', draft: 'v1', self_grade: 'v1' },
    raw_llm_outputs: {
      classify_raw: prev.classify_raw,
      draft_raw: prev.draft_raw,
      self_grade_raw: rawSg,
      classify_parse_error: prev.classify_parse_error,
      draft_parse_error: prev.draft_parse_error,
      sg_parse_error
    }
  }
};

// Build a short-circuit callback payload (no draft, no self-grade).
// Reached when classify failed, retrieval was empty, or top1 < hard floor.
const prev = $json;
const latency_ms = Date.now() - (prev.t0 || Date.now());
return {
  json: {
    ticket_id: prev.ticket_id,
    classification: prev.classification ?? null,
    top_chunks: prev.top_chunks ?? [],
    draft_response: null,
    cited_docs: [],
    self_grade: null,
    verdict: prev.short_circuit_verdict || 'error',
    verdict_reason: prev.short_circuit_reason || 'unspecified',
    latency_ms,
    prompt_versions: { classify: 'v1', draft: null, self_grade: null },
    raw_llm_outputs: {
      classify_raw: prev.classify_raw,
      classify_parse_error: prev.classify_parse_error
    }
  }
};
